import React from "react";
import { Link } from "react-router-dom";

class SinglePost extends React.Component {

    handleLike = (e) => {
        e.preventDefault();

        const { id, like } = this.state;

        // Toggle state immediately for fast UI response
        this.setState({ like: like ? 0 : 1 });

        fetch("http://127.0.0.1:8000/api/posts/like/" + id, {
            method: "GET",
        })
            .then(async (res) => {
                if (!res.ok) {
                    const errText = await res.text();
                    throw new Error(errText || "Failed to like post");
                }
                return res.json();
            })
            .catch((err) => {
                console.error(err);
                // Revert like on error
                this.setState({ like });
            });
    };

    render() {
        return (
            <div className="card mb-4 shadow-sm item-back text-color overflow-hidden rounded-4 boder">
                <Link to={`/post/${this.props.id}`} className="text-decoration-none">
                    <img src={this.props.base_URL + this.props.img} alt="Post" className="post-img rounded-top-4" />
                </Link>

                <div className="card-body">

                    <h3 className="card-title text-color">{this.props.title}</h3>

                    <p className="text-muted">{this.props.display_time}</p>

                    <p className="card-text text-color">{this.props.text}</p>

                    <div className="d-flex align-items-center gap-2 mb-3">

  {this.props.is_like ? (
                        <span id="span_like">
                            <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24"
                                fill="red" viewBox="0 0 24 24">
                                <path d="M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 
                                2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 
                                4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 
                                3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 
                                11.54L12 21.35z" />
                            </svg>
                        </span>
      ) : (
<svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" fill="currentColor"
     class="bi bi-heart-fill" viewBox="0 0 16 16">
  <path fill-rule="evenodd"
        d="M8 1.314C12.438-3.248 23.534 4.735 8 15
           -7.534 4.736 3.562-3.248 8 1.314z"/>
</svg>
          )}

                        <span id="count_like">{this.props.count_like}</span>

                        <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24"
                            fill="currentColor" className="bi bi-chat" viewBox="0 0 16 16">
                            <path d="M2.678 11.894a1 1 0 0 1 .287.801 
                            11 11 0 0 1-.398 2c1.395-.323 
                            2.247-.697 2.634-.893a1 1 0 0 
                            1 .71-.074A8 8 0 0 0 8 
                            14c3.996 0 7-2.807 7-6s-3.004-6-7-6-7 
                            2.808-7 6c0 1.468.617 2.83 1.678 3.894"/>
                        </svg>

                        <span>{this.props.count_comment}</span>

                    </div>

                       <div className="d-flex align-items-center my-3">

                        <img src={this.props.base_URL + this.props.img}
                            alt="User"
                            className="user-img me-3 rounded-circle boder"
                        />

                        <div>
                            <Link to="/profile" className="text-decoration-none text-color pt-1 pb-1 rounded-3">
                                {this.props.name}
                            </Link>
                        </div>

                    </div>

                </div>

            </div>
        );
    }
}

export default SinglePost;
